// 앞을 빼면
private TraceStatus before(String message) {
    return trace.begin(message);
}

// 뒤를 빼면
private void after(TraceStatus status) {
    trace.end(status);
}

public void orderItem(String itemId) {
    TraceStatus status = null;
    try {
        status = before("OrderService.orderItem()");
        orderRepository.save(itemId);
        after(status);
    } catch (Exception e) {
        trace.exception(status, e);
        throw e;
    }
}

