-- 뚫는 길 둘

// ① 상속 — 자식이 4 번 줄을 채운다
abstract class AbstractTemplate {
    void execute() {
        TraceStatus status = null;
        try {
            status = trace.begin(getMessage());
            call();                              // 여기를 자식이 채운다
            trace.end(status);
        } catch (Exception e) { ... }
    }
    protected abstract void call();
}

// ② 위임 — 부르는 쪽이 4 번 줄을 넘긴다
class TraceTemplate {
    void execute(String message, Runnable body) {
        TraceStatus status = null;
        try {
            status = trace.begin(message);
            body.run();                          // 여기를 인자가 채운다
            trace.end(status);
        } catch (Exception e) { ... }
    }
}

